    /// <summary>
    /// Set pricing rule Rec Id to trade agreement line
    /// </summary>
    /// <param name = "_pricingRuleFieldId">Pricing rule fields depends on source level</param>
    /// <param name = "_pricingRuleRecID">Pricing rule reference</param>
    public void setPricingRuleReference(FieldId _pricingRuleFieldId, RefRecId _pricingRuleRecID)
    {
        ttsbegin;

        this.selectForUpdate(true);
        this.(_pricingRuleFieldId) = _pricingRuleRecID; 

        this.update();

        ttscommit;
    }

/// <summary>
/// Display pricing attribute group name for header group
/// </summary>
/// <returns>Pricing attribute group name</returns>
[SysClientCacheDataMethodAttribute(true)]
public display GUPPricingAttributeGroupNameHeader displayPricingAttributeGroupNameHeader()
{
    return GUPPricingRule::find(this.PricingRuleHeader).pricingAttributeGroup().Name;
}

/// <summary>
/// Display pricing attribute group name for line group
/// </summary>
/// <returns>Pricing attribute group name</returns>
[SysClientCacheDataMethodAttribute(true)]
public display GUPPricingAttributeGroupNameLine displayPricingAttributeGroupNameLine()
{
    return GUPPricingRule::find(this.PricingRuleLine).pricingAttributeGroup().Name;
}

/// <summary>
/// Display pricing attributes related to Header pricing group
/// </summary>
/// <returns>Pricing attribute details</returns>
[SysClientCacheDataMethodAttribute(true)]
public display GUPPricingAttributeDetails pricingAttributeDetailsHeader()
{
    return this.getPricingAttributeDetails(this.PricingRuleHeader);
}

/// <summary>
/// Display pricing attributes related to Line pricing group
/// </summary>
/// <returns>Pricing attribute details</returns>
[SysClientCacheDataMethodAttribute(true)]
public display GUPPricingAttributeDetails pricingAttributeDetailsLine()
{
    return this.getPricingAttributeDetails(this.PricingRuleLine);
}

    /// <summary>
    /// Find and format pricing attributes with related conditions
    /// </summary>
    /// <param name = "_pricingRuleRecId">Pricing rule reference</param>
    /// <returns>Pricing attributes with related conditions</returns>
    public GUPPricingAttributeDetailsPreview getPricingAttributeDetails(GUPPricingRuleRecId _pricingRuleRecId)
    {
        GUPPricingRuleCondition             pricingRuleCondition;
        GUPPricingAttributeDetailsPreview   displayDetails;

        GUPPricingAttributeRepository::getAllPricingAttributes();

        while select pricingRuleCondition
            where pricingRuleCondition.RuleId == _pricingRuleRecId
        {
            str conditionValue = GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(
                                                                                pricingRuleCondition.pricingAttribute().getName(),
                                                                                pricingRuleCondition.ConditionValue);
            displayDetails += strFmt('%1: %2; ',
                                        pricingRuleCondition.pricingAttribute().getName(),
                                        conditionValue);
        }

        return displayDetails;
    }

    /// <summary>
    /// Initiates the current table buffer by using the specified table buffer.
    /// </summary>
    /// <param name="_priceDiscAdmTrans">
    /// A <c>PriceDiscAdmTrans</c> table buffer.
    /// </param>
    public void initFromPriceDiscAdmTrans(PriceDiscAdmTrans _priceDiscAdmTrans)
    {
        next initFromPriceDiscAdmTrans(_priceDiscAdmTrans);

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            this.PriceComponentCombination  = _priceDiscAdmTrans.PriceComponentCombination;
            this.PricingRuleHeader          = GUPPricingRule::find(_priceDiscAdmTrans.PricingRuleHeader).copy().RecId;
            this.PricingRuleLine            = GUPPricingRule::find(_priceDiscAdmTrans.PricingRuleLine).copy().RecId;
            this.PriceApplyAdjustment       = _priceDiscAdmTrans.PriceApplyAdjustment;
            this.UnitAppliesToAll           = _priceDiscAdmTrans.UnitAppliesToAll;
        }
    }

    /// <summary>
    ///     Initiates a <c>PriceDiscAdmTrans</c> record from a <c>PriceDiscTable</c> record.
    /// </summary>
    /// <param name="_priceDiscTable">
    ///     A <c>PriceDiscTable</c> record buffer.
    /// </param>
    public void initFromPriceDiscTable(PriceDiscTable _priceDiscTable)
    {
        next initFromPriceDiscTable(_priceDiscTable);

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            this.PriceComponentCombination  = _priceDiscTable.PriceComponentCombination;
            this.PricingRuleHeader          = GUPPricingRule::find(_priceDiscTable.PricingRuleHeader).copy().RecId;
            this.PricingRuleLine            = GUPPricingRule::find(_priceDiscTable.PricingRuleLine).copy().RecId;
            this.PriceApplyAdjustment       = _priceDiscTable.PriceApplyAdjustment;
            this.UnitAppliesToAll           = _priceDiscTable.UnitAppliesToAll;
        }
    }

    /// <summary>
    /// Specifies if current journal is enabled for pricing attributes
    /// </summary>
    /// <returns>True if pricing attributes are enabled in journal name record; Otherwise false</returns>
    public boolean isPricingAttributeEnabled()
    {
        PriceDiscAdmTable   priceDiscAdmTable = PriceDiscAdmTable::find(this.JournalNum);
        PriceDiscAdmName    priceDiscAdmName = PriceDiscAdmName::find(priceDiscAdmTable.JournalName);

        return priceDiscAdmName.PriceDiscPriceAttributeEnable;
    }

    /// <summary>
    /// Check price component for lines where pricing attributes are enabled
    /// </summary>
    /// <returns>True if price component is specified and pricing group combination is valid; Otherwise false</returns>
    public boolean checkPriceComponent()
    {
        boolean ret = true;

        if (this.isPricingAttributeEnabled())
        {
            if (!this.PriceComponentCombination)
            {
                ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPPriceComponentCodeEmpty", this.LineNum));
            }
            else if (!GUPPriceComponentCodePriceAttributeGroupCombination::exist(this.PriceComponentCombination))
            {
                ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPCombinationNotExistError", this.LineNum));
            }
        }

        return ret;
    }

    /// <summary>
    /// Validates the item relation value.
    /// For pricing attributes this validation should skip item validation and run pricing group validation instead
    /// </summary>
    /// <returns>true if the item relation value is valid; otherwise, false.</returns>
    protected boolean isItemRelationValid()
    {
        boolean ok = next isItemRelationValid();

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && this.isPricingAttributeEnabled())
        {
            ok = true;
        }

        return ok;
    }
